  "source_title": "03_graco_check_mate_200_pumps_manual.pdf",
  "nodes": {
    "Component": [
      {
        "component_id": "comp_pump",
        "name": "Pump",
        "description": "Pump mounted for the planned installation and grounded before operation.",
        "category": "pumping"
      },
      {
        "component_id": "comp_bleed_type_master_air_valve",
        "name": "Bleed-type master air valve",
        "description": "Relieves air trapped between the valve and the pump or air motor after the air is shut off.",
        "category": "air line"
      },
      {
        "component_id": "comp_fluid_drain_valve",
        "name": "Fluid drain valve",
        "description": "Relieves fluid pressure in the displacement pump, hose, and gun.",
        "category": "fluid line"
      },
      {
        "component_id": "comp_pump_runaway_valve",
        "name": "Pump runaway valve",
        "description": "Senses when the pump is running too fast and automatically shuts off air to the motor.",
        "category": "air line"
      },
      {
        "component_id": "comp_air_line_lubricator",
        "name": "Air line lubricator",
        "description": "Provides automatic air motor lubrication.",
        "category": "air line"
      },
      {
        "component_id": "comp_air_regulator",
        "name": "Air regulator",
        "description": "Controls pump speed and outlet pressure by adjusting the air pressure to the pump.",
        "category": "air line"
      },
      {
        "component_id": "comp_air_line_filter",
        "name": "Air line filter",
        "description": "Removes harmful dirt and moisture from the compressed air supply.",
        "category": "air line"
      },
      {
        "component_id": "comp_fluid_regulator",
        "name": "Fluid regulator",
        "description": "Controls fluid pressure to the gun or valve and dampens pressure surges.",
        "category": "fluid line"
      },
      {
        "component_id": "comp_gun_or_valve",
        "name": "Gun or valve",
        "description": "Dispenses the fluid.",
        "category": "fluid dispensing"
      },
      {
        "component_id": "comp_gun_swivel",
        "name": "Gun swivel",
        "description": "Allows freer gun movement.",
        "category": "fluid dispensing"
      },
      {
        "component_id": "comp_air_and_fluid_hoses",
        "name": "Air and fluid hoses",
        "description": "Hoses used in the system; they must be properly sized, pressure-rated, and grounded.",
        "category": "fluid and air lines"
      },
      {
        "component_id": "comp_air_line_quick_disconnect_coupler",
        "name": "Air line quick disconnect coupler",
        "description": "Required for pumps mounted on the pneumatic elevator cart; connects the air hose to the air manifold.",
        "category": "air line"
      },
      {
        "component_id": "comp_pneumatic_elevator_cart",
        "name": "Pneumatic elevator cart",
        "description": "A mounting option shown for the pump in the typical installation.",
        "category": "mounting"
      },
      {
        "component_id": "comp_wiper_plate",
        "name": "Wiper plate",
        "description": "Used with the pump when it is mounted on a pneumatic elevator cart or pail ram.",
        "category": "fluid handling"
      },
      {
        "component_id": "comp_pail_ram",
        "name": "Pail ram",
        "description": "A mounting option for the pump, used with a wiper plate.",
        "category": "mounting"
      },
      {
        "component_id": "comp_air_motor",
        "name": "Air motor",
        "description": "The pump motor supplied with air through the air line accessories.",
        "category": "motor"
      }
    ],
    "Symptom": [],
    "FailureMode": [],
    "CorrectiveAction": [],
    "ErrorCode": []
  },
  "relations": []
}
